 // Original opening and tutorial copy, retained from index.html.
 static readonly string[] cutLabels={"SYSTEM BOOT","RIG ONLINE","MARKET LINK","EXPAND RIG","QUANTUM GOAL"},cutTitles={"낡은 채굴실","첫 번째 GPU","가상 코인 시장 접속","더 강한 장비","목표: QUANTUM"},cutArt={"●\nPOWER OFF\n...\nSIGNAL FOUND","▣\nRTX 1090\nTEMP 30°C\nSTATUS : ONLINE","₿ Ξ Ð ✦ Q\nMARKET LINK : CONNECTED\nVOLATILITY : ACTIVE","▣  ▣  ▣\nGPU / COOLING / POWER\nBUILD YOUR RIG","⚛\nRTX 6090 QUANTUM\nREBIRTH PROTOCOL\nLOCKED"},cutText={"불 꺼진 작은 방.\n책상 위에는 오래된 채굴 장비 한 대만 남아 있다.","전원을 넣자 RTX 1090의 팬이 천천히 돌기 시작한다.\n이 한 장이 모든 것의 시작이다.","채굴한 코인은 시장에서 현금으로 바꿀 수 있다.\n하지만 시세는 계속 움직이고, 어떤 코인은 갑자기 폭등하거나 급락한다.","더 좋은 GPU를 사고, 냉각을 강화하고, 새로운 코인을 해금하라.\n작은 랙은 점점 거대한 채굴 시스템으로 변한다.","최종 목표는 RTX 6090 QUANTUM과 환생 프로토콜.\n지금부터 첫 번째 채굴을 시작한다."};
 static readonly string[] tutTitles={"1. GPU를 눌러 채굴","2. 코인을 현금으로 판매","3. GPU 업그레이드","4. 온도와 GPU 쿨링","5. 전력과 오버클럭","6. 계약과 시장 이벤트","7. 환생과 FORK"},tutText={"랙에 장착된 GPU를 클릭하면 코인을 채굴합니다.\n\nGPU가 여러 장이면 클릭 한 번에 장착된 GPU가 모두 같이 채굴합니다.","방 오른쪽 컴퓨터를 누르면 거래소가 열립니다.\n\n채굴한 코인을 현재 게임 시세로 팔아 ₩ 현금을 만들고, 그 돈으로 장비를 구매합니다.","[SHOP]에서 GPU를 구매하거나 [GPU]에서 1번 슬롯 GPU를 업그레이드할 수 있습니다.\n\n상위 GPU를 보유하면 ETHER-X, DOGE-X 같은 새로운 코인도 순서대로 해금됩니다.","채굴과 오버클럭은 GPU 온도를 올립니다.\n\n[COOL]에서 GPU 전용 공랭/수냉을 장착하세요. GPU 하나라도 100°C에 도달하면 시스템이 파산합니다.","[OC]는 채굴 성능을 높이지만 발열도 증가합니다.\n\nGPU 전력 사용량에 따라 실제 게임 현금에서 전기요금이 주기적으로 차감됩니다.","거래소에는 채굴/판매 계약이 있습니다. 목표를 완료하면 현금 보상을 받을 수 있습니다.\n\n랜덤 이벤트로 해금된 특정 코인이 갑자기 급등하거나 급락할 수도 있습니다.","최종 RTX 6090 QUANTUM을 준비하고 환생 조건을 달성하면 FORK를 얻습니다.\n\n환생하면 이번 회차 장비는 초기화되지만 FORK 업그레이드는 남아 다음 회차 성장을 빠르게 해줍니다."};
 void StopIntro(){if(typing!=null)StopCoroutine(typing);typingNow=false;if(intro!=null){intro.gameObject.SetActive(false);Destroy(intro.gameObject);}intro=null;g.IntroPaused=false;}
