 void RenderOpening(){StopIntro();g.IntroPaused=true;intro=Box(screen,"Opening",0,0,480,854,C("02040a"));var b=Box(intro,"Cutscene",25,148,430,535,Dark,C("303a50"),3);Text(b,cutLabels[introIndex],12,8,300,28,12,Cyan);Button(b,"SKIP",347,8,70,29,FinishOpening,Red,10);Box(b,"Visual",3,44,424,220,introIndex==2?C("241b39"):introIndex==4?C("123e3a"):C("14283e"));Text(b,cutArt[introIndex],18,68,394,176,22,Green,TextAnchor.MiddleCenter);Text(b,cutTitles[introIndex],16,280,398,33,18,Gold);typed=Text(b,"",16,321,398,125,16);fullCaption=cutText[introIndex];typing=StartCoroutine(TypeCaption());Text(b,new string('■',introIndex+1)+new string('□',4-introIndex),16,466,185,40,13,Cyan);Button(b,introIndex==4?"[ 채굴 시작 ]":"[ 계속 ]",260,470,151,42,()=>{if(typingNow){StopCoroutine(typing);typed.text=fullCaption;typingNow=false;}else if(introIndex<4){introIndex++;RenderOpening();}else FinishOpening();});}
 IEnumerator TypeCaption(){typingNow=true;for(int i=0;i<=fullCaption.Length;i++){typed.text=fullCaption.Substring(0,i);yield return new WaitForSecondsRealtime(.022f);}typingNow=false;}
