[RequireComponent(typeof(CanvasRenderer))]
public class CandleChart:MaskableGraphic {
 public MarketManager market;public string coinId;
 protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();if(market==null)return;var series=market.Series(coinId);if(series==null||series.candles.Count==0)return;var cs=series.candles;float lo=float.MaxValue,hi=float.MinValue;foreach(var c in cs){lo=Mathf.Min(lo,c.low);hi=Mathf.Max(hi,c.high);}float pad=Mathf.Max(Catalog.Coin(coinId).basePrice*.01f,(hi-lo)*.12f);lo-=pad;hi+=pad;float w=rectTransform.rect.width,h=rectTransform.rect.height;Func<float,float> y=p=>h*(p-lo)/(hi-lo);for(int i=0;i<5;i++)Quad(vh,0,h*i/4,w,1,new Color(.21f,.23f,.28f));float step=w/cs.Count;for(int i=0;i<cs.Count;i++){var c=cs[i];float x=(i+.5f)*step;Color color=c.close>=c.open?new Color(1,.38f,.36f):new Color(.31f,.60f,1);Quad(vh,x,y(c.low),1,Mathf.Max(1,y(c.high)-y(c.low)),color);Quad(vh,x-step*.3f,y(Mathf.Min(c.open,c.close)),Mathf.Max(1,step*.6f),Mathf.Max(1,Mathf.Abs(y(c.close)-y(c.open))),color);}}
 void Quad(VertexHelper vh,float x,float y,float w,float h,Color c){int n=vh.currentVertCount;Vector2 o=rectTransform.rect.min;vh.AddVert(new Vector3(x+o.x,y+o.y),c,Vector2.zero);vh.AddVert(new Vector3(x+w+o.x,y+o.y),c,Vector2.zero);vh.AddVert(new Vector3(x+w+o.x,y+h+o.y),c,Vector2.zero);vh.AddVert(new Vector3(x+o.x,y+h+o.y),c,Vector2.zero);vh.AddTriangle(n,n+1,n+2);vh.AddTriangle(n,n+2,n+3);}
}
